<?php
namespace App\Http\Controllers\Api\V1;
use App\Jobs\ExportTenantData; use App\Models\TenantExport; use App\Services\AuthorizationService; use App\Support\TenantContext; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
final class TenantExportController { public function request(Request $r,AuthorizationService $auth){$t=app(TenantContext::class)->id();abort_unless($auth->allows($r->user(),$t,'organization.manage'),403);$export=TenantExport::create(['tenant_id'=>$t,'requested_by'=>$r->user()->id,'state'=>'queued']);ExportTenantData::dispatch($t,$export->id);return response()->json(['data'=>$export],202);} public function index(Request $r){return response()->json(['data'=>TenantExport::where('tenant_id',app(TenantContext::class)->id())->where('requested_by',$r->user()->id)->latest()->paginate(25)]);} public function download(Request $r,TenantExport $export){abort_unless($export->tenant_id===app(TenantContext::class)->id()&&$export->requested_by===$r->user()->id,404);abort_unless($export->state==='completed'&&$export->private_path,409);return response()->download(Storage::disk('local')->path($export->private_path),'tenant-export.json');} }
